mapper.select:
SELECT 

ORDER BY e.started_at ASC, e.id ASC
LIMIT #{limit} OFFSET #{offset}

SELECT FROM execution_logs e JOIN todos t ON t.id = e.todo_id JOIN plans p ON p.id = t.plan_id WHERE p.user_id = #{userId} AND p.deleted_at IS NULL AND t.deleted_at IS NULL AND e.started_at < e.ended_at AND e.started_at < #{endedAt} AND #{startedAt} < e.ended_at
AND e.id <> #{excludeId}
ORDER BY e.started_at ASC, e.id ASC LIMIT 1

SELECT COALESCE(MAX(r.revision_no), 0) + 1
FROM execution_log_revisions r
WHERE r.execution_log_id = #{logId}
